package com.fasttravel.controller;import com.fasttravel.dto.ApiResponse;import com.fasttravel.dto.BookingDTO.*;import com.fasttravel.service.BookingService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/bookings") @RequiredArgsConstructor public class BookingController{private final BookingService service;private Long uid(Authentication a){return(Long)a.getDetails();}@PostMapping public ApiResponse<?> create(Authentication a,@Valid @RequestBody CreateRequest r,HttpServletRequest q){return ApiResponse.ok("Đã giữ ghế trong 15 phút",service.create(uid(a),r,q.getRemoteAddr()));}@GetMapping public ApiResponse<?> history(Authentication a){return ApiResponse.ok(service.history(uid(a)));}}
